def floodFill(image, sr, sc, color):
    res = [row[:] for row in image]
    old = res[sr][sc]
    if old == color:
        return res
    rows, cols = len(res), len(res[0])
    res[sr][sc] = color
    stack = [(sr, sc)]
    while stack:
        y, x = stack.pop()
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ny, nx = y + dy, x + dx
            if 0 <= ny < rows and 0 <= nx < cols and res[ny][nx] == old:
                res[ny][nx] = color
                stack.append((ny, nx))
    return res
